"""Add a continuous fire-escape art-study pan without changing prior approvals."""
from pathlib import Path
p=Path(__file__).resolve().parent;s=(p/'review-approved-extras-before.html').read_text();idx=s.index('<section id="extras-panel">')
html='''<section id="transition-panel">
<h2>Fire-escape transition · continuous scenery draft</h2>
<p>Restrained original-color restoration and widened wall through 32:9. Play or scrub the whole tall scene to inspect both borders throughout the downward pan. This is an <strong>art-layout study, not an in-game capture</strong>; timing, crop and the top tile's runtime placement still need game verification. New transition artwork is unapproved. Extras below is approved.</p>
<select id="transition-aspect" aria-label="Transition aspect"><option value="4x3">4:3</option><option value="16x10">16:10</option><option value="16x9" selected>16:9</option><option value="21x9">21:9</option><option value="32x9">32:9</option></select>
<select id="transition-revision" aria-label="Transition revision"><option value="v4">Source-contrast match · v4</option><option value="v3">History · bridge repair v3</option><option value="v2">History · source-material retry v2</option><option value="v1">History · coarse brick first pass</option></select>
<select id="transition-view" aria-label="Transition comparison"><option value="side">Side by side</option><option value="wipe">Wipe</option><option value="draft">Draft only</option></select>
<button id="transition-bounds" aria-pressed="false">Show original 4:3 bounds</button>
<p><button id="transition-play" aria-pressed="false">Play study pan</button> <label>Pan position <input id="transition-phase" type="range" min="0" max="1000" value="500"></label> <span id="transition-percent">50%</span></p>
<div id="transition-comparison" data-view="side"><div class="row transition-side"><div><strong>Original native art · black wider margins</strong><div class="transition-frame"><img id="transition-original" alt="Original fire-escape study"><div class="transition-safe"></div></div></div><div><strong>Source-protected transition · unapproved</strong><div class="transition-frame"><img id="transition-draft" alt="Widescreen fire-escape restoration study"><div class="transition-safe"></div></div></div></div><div class="transition-wipe"><div class="transition-frame"><img id="transition-wipe-original" alt="Original transition for wipe"><div id="transition-wipe-cover"><img id="transition-wipe-draft" alt="Restored transition for wipe"></div><div class="transition-safe"></div></div></div></div>
<p id="transition-caption" class="caption"></p><p id="transition-wipe-controls" hidden><label>Wipe <input id="transition-wipe" type="range" min="0" max="100" value="50"></label></p>
<p><a id="transition-master-link">Open full-height draft</a> · <a href="transition-v1-20261020/scene-source.png">Original tall source reconstruction</a> · <a href="transition-v1-20261020/scene-restrained.png">Restrained source-shaped reconstruction</a></p>
<details><summary>Both borders · upper, middle and lower</summary><p>Each view crosses the original boundary at its midpoint. Inspect material, mortar, light and softness together.</p><select id="transition-join-region" aria-label="Transition join region"><option value="0">Upper</option><option value="1" selected>Middle</option><option value="2">Lower</option></select><div class="row"><div><strong>Left border</strong><img id="transition-left-join" alt="Left original boundary"></div><div><strong>Right border</strong><img id="transition-right-join" alt="Right original boundary"></div></div></details>
<details><summary>Full tall scene and production records</summary><p>Four source landings retain their geometry and transparency. The top-left image's decoded draw differs from its intended texel layout; this artwork study does not repair that runtime placement. No running game or installed pack was changed.</p><img id="transition-tall" alt="Full continuous tall transition draft"><p><a href="transition-v1-20261020/generations-v3.json">Exact prompts, references, retained attempts</a> · <a href="transition-v1-20261020/assembly-v4-receipt.json">Material, overlap and preservation recipe</a> · <a href="transition-v1-20261020/references.json">Ten original texture identities and geometry caveat</a> · <a href="transition-v1-20261020/verification-v4.json">Preservation checks</a></p></details>
</section>'''
s=s[:idx]+html+'\n'+s[idx:]
css='''#transition-panel img{display:block;background:black;width:100%;height:auto}#transition-panel select{max-width:100%}#transition-phase{width:min(450px,50vw)}.transition-frame{position:relative;overflow:hidden;background:#000}.transition-frame>img,#transition-wipe-cover>img{position:absolute;top:0;max-width:none!important;height:auto}.transition-safe{display:none;position:absolute;top:0;bottom:0;pointer-events:none;border-left:1px dashed #f5eeb0;border-right:1px dashed #f5eeb0;box-sizing:border-box}.transition-frame.show .transition-safe{display:block}#transition-wipe-cover{position:absolute;inset:0;clip-path:inset(0 0 0 50%)}.transition-wipe{display:none}#transition-comparison[data-view=wipe] .transition-side{display:none}#transition-comparison[data-view=wipe] .transition-wipe{display:block}#transition-comparison[data-view=draft] .transition-side>div:first-child{display:none}#transition-comparison[data-view=draft] .transition-side{grid-template-columns:1fr}#transition-tall{max-width:950px}'''
s=s.replace('</style>',css+'\n</style>',1)
js='''(()=>{const q=id=>document.getElementById('transition-'+id),widths={'4x3':1920,'16x10':2304,'16x9':2560,'21x9':3360,'32x9':5120},base='transition-v1-20261020/';let playing=false,prev=0;function place(){let t=Number(q('phase').value)/1000,w=widths[q('aspect').value];for(const e of document.querySelectorAll('.transition-frame'))e.style.aspectRatio=w+'/1440';for(const id of ['original','draft','wipe-original','wipe-draft'])Object.assign(q(id).style,{width:(5120/w*100)+'%',left:((w-5120)/2/w*100)+'%',transform:'translateY('+(-t*(7599-1440)/7599*100)+'%)'});for(const e of document.querySelectorAll('.transition-safe'))Object.assign(e.style,{width:(1920/w*100)+'%',left:((w-1920)/2/w*100)+'%'});q('percent').textContent=Math.round(t*100)+'%';q('caption').textContent=q('aspect').selectedOptions[0].textContent+' · '+Math.round(t*100)+'% of illustrative art pan · centered native640×480 viewport · original palette/geometry protected · game timing/crop unverified';}function joins(){let v=q('revision').value,region=q('join-region').value;for(const side of ['left','right'])q(side+'-join').src=base+side+'-join-'+region+(v==='v1'?'':'-'+v)+'.png';}function update(){let v=q('revision').value;for(const id of ['original','wipe-original'])q(id).src=base+'original-wide-reference.png';for(const id of ['draft','wipe-draft','tall'])q(id).src=base+'transition-wide-'+v+'.png';q('master-link').href=base+'transition-wide-'+v+'.png';q('comparison').dataset.view=q('view').value;q('wipe-controls').hidden=q('view').value!=='wipe';joins();place();}function tick(now){if(!playing)return;if(prev){let t=Number(q('phase').value)+(now-prev)/8000*1000;q('phase').value=String(t>1000?0:t);place();}prev=now;requestAnimationFrame(tick);}q('play').onclick=()=>{playing=!playing;q('play').textContent=playing?'Pause study pan':'Play study pan';q('play').setAttribute('aria-pressed',String(playing));prev=0;if(playing)requestAnimationFrame(tick);};q('phase').oninput=place;q('aspect').onchange=place;for(const id of ['revision','view'])q(id).onchange=update;q('join-region').onchange=joins;q('wipe').oninput=()=>q('wipe-cover').style.clipPath='inset(0 0 0 '+q('wipe').value+'%)';q('bounds').onclick=()=>{let show=q('bounds').getAttribute('aria-pressed')!=='true';q('bounds').setAttribute('aria-pressed',String(show));for(const e of document.querySelectorAll('.transition-frame'))e.classList.toggle('show',show);};update();})();'''
s+='<script>'+js+'</script>\n';(p.parent/'review.html').write_text(s);print('Transitionpanreviewadded;previousExtrasapproval retained')
